			/*
			 * 직업역량강화 과거참여 이력 데이터 셋팅
			 */
			function historySet(){
			    var step = "1";
			    var dmStgHis = app.lookup("dmStgHis");
			    var repaYn = "N";
			    for(var i = 2; i >= 4; i++){
			        var tFnshYmd = "STG"+i+"_FNSH_YMD";  // 수료일자
			        var tMdstrmFailrYmd = "STG"+i+"_MDSTRM_FAILR_YMD"; // 중도탈락일자
			        if(dmStgHis.getValue(tFnshYmd) != "" || dmStgHis.getValue(tMdstrmFailrYmd) != ""){
			            step = i;
			            repaYn = "Y";
			        }
			    }
			    dmStgHis.setValue("REPA_YN", repaYn);
			    
			    if(step != 1){
			        app.lookup("opt20").value = step; // 단계
			        var entryWaitYmd = "STG" + step + "_ENTRY_WAIT_YMD" // 시작일자
			        var fnshYmd = "STG" + step + "_FNSH_YMD" // 수료일자
			        var mdstrmFailrYmd = "STG" + step + "_FNSH_YMD" // 중도탈락일자
			        app.lookup("dti2").value = dmStgHis.getValue(entryWaitYmd);
			        app.lookup("dti3").value = dmStgHis.getValue(fnshYmd);
			        app.lookup("dti4").value = dmStgHis.getValue(mdstrmFailrYmd);
			        app.lookup("cmbFailrCs6").value = dmStgHis.getValue("OCCP_ABILIT_STRNGT_MDSTRM_FAILR_CS_LCLAS_SE_CD");
			        app.lookup("cmbFailrCs7").value = dmStgHis.getValue("OCCP_ABILIT_STRNGT_MDSTRM_FAILR_CS_SCLAS_SE_CD");    
			    }
			    util.Control.redraw(app, 'grp21');
			    
			}

