			/*
			 * 수료일자, 중도탈락일자 enable 설정
			 */
			function fnshFailrSet(){
			    var dmOutcomeDetail = app.lookup("dmOutcomeDetail");
			    if(dmOutcomeDetail.getValue("STG2_MDSTRM_FAILR_YMD") != "" && dmOutcomeDetail.getValue("STG2_MDSTRM_FAILR_YMD") != null){ // 2단계 중도탈락
			        app.lookup("STG2_FNSH_YMD_DTI").enabled = false;
			        app.lookup("STG3_FNSH_YMD_DTI").enabled = false;
			        app.lookup("STG4_FNSH_YMD_DTI").enabled = false;
			        
			        app.lookup("STG3_MDSTRM_FAILR_YMD_DTI").enabled = false;
			        app.lookup("STG4_MDSTRM_FAILR_YMD_DTI").enabled = false;
			        
			        dmOutcomeDetail.setValue("STG2_FNSH_YMD", "");
			        dmOutcomeDetail.setValue("STG3_FNSH_YMD", "");
			        dmOutcomeDetail.setValue("STG4_FNSH_YMD", "");
			        
			        dmOutcomeDetail.setValue("STG3_MDSTRM_FAILR_YMD", "");
			        dmOutcomeDetail.setValue("STG4_MDSTRM_FAILR_YMD", "");
			        
			        app.lookup("cmbFailrCs2").enabled = true;
			        app.lookup("cmbFailrCs3").enabled = true;
			        return;
			    } else {
			        app.lookup("STG2_FNSH_YMD_DTI").enabled = true;
			        app.lookup("STG3_FNSH_YMD_DTI").enabled = true;
			        app.lookup("STG4_FNSH_YMD_DTI").enabled = true;
			        
			        app.lookup("STG3_MDSTRM_FAILR_YMD_DTI").enabled = true;
			        app.lookup("STG4_MDSTRM_FAILR_YMD_DTI").enabled = true;
			    }
			    
			    if(dmOutcomeDetail.getValue("STG2_FNSH_YMD") != "" && dmOutcomeDetail.getValue("STG2_FNSH_YMD") != null){ // 2단계 수료
			        app.lookup("STG2_MDSTRM_FAILR_YMD_DTI").enabled = false;
			    } else {
			        app.lookup("STG2_MDSTRM_FAILR_YMD_DTI").enabled = true;
			    }
			    
			    if(dmOutcomeDetail.getValue("STG3_MDSTRM_FAILR_YMD") != "" && dmOutcomeDetail.getValue("STG3_MDSTRM_FAILR_YMD") != null){ // 3단계 중도탈락
			        app.lookup("STG3_FNSH_YMD_DTI").enabled = false;
			        app.lookup("STG4_FNSH_YMD_DTI").enabled = false;
			        
			        app.lookup("STG4_MDSTRM_FAILR_YMD_DTI").enabled = false;
			        
			        dmOutcomeDetail.setValue("STG3_FNSH_YMD", "");
			        dmOutcomeDetail.setValue("STG4_FNSH_YMD", "");
			        
			        dmOutcomeDetail.setValue("STG4_MDSTRM_FAILR_YMD", "");
			        
			        app.lookup("cmbFailrCs2").enabled = true;
			        app.lookup("cmbFailrCs3").enabled = true;
			        return;
			    } else {
			        app.lookup("STG3_FNSH_YMD_DTI").enabled = true;
			        app.lookup("STG4_FNSH_YMD_DTI").enabled = true;
			        
			        app.lookup("STG4_MDSTRM_FAILR_YMD_DTI").enabled = true;
			    }
			    
			    if(dmOutcomeDetail.getValue("STG3_FNSH_YMD") != "" && dmOutcomeDetail.getValue("STG3_FNSH_YMD") != null){ // 3단계 수료
			        app.lookup("STG3_MDSTRM_FAILR_YMD_DTI").enabled = false;
			    } else {
			        app.lookup("STG3_MDSTRM_FAILR_YMD_DTI").enabled = true;
			    }
			    
			    if(dmOutcomeDetail.getValue("STG4_MDSTRM_FAILR_YMD") != "" && dmOutcomeDetail.getValue("STG4_MDSTRM_FAILR_YMD") != null){ // 4단계 중도탈락
			        app.lookup("STG4_FNSH_YMD_DTI").enabled = false;
			        
			        dmOutcomeDetail.setValue("STG4_FNSH_YMD", "");
			        
			        app.lookup("cmbFailrCs2").enabled = true;
			        app.lookup("cmbFailrCs3").enabled = true;
			        return;
			    } else {
			        app.lookup("STG4_FNSH_YMD_DTI").enabled = true;
			    }
			    
			    if(dmOutcomeDetail.getValue("STG4_FNSH_YMD") != "" && dmOutcomeDetail.getValue("STG4_FNSH_YMD") != null){ // 4단계 수료
			        app.lookup("STG4_MDSTRM_FAILR_YMD_DTI").enabled = false;
			    } else {
			        app.lookup("STG4_MDSTRM_FAILR_YMD_DTI").enabled = true;
			    }
			    
			    app.lookup("cmbFailrCs2").enabled = false;
			    app.lookup("cmbFailrCs3").enabled = false;
			    
			    dmOutcomeDetail.setValue("OCCP_ABILIT_STRNGT_MDSTRM_FAILR_CS_LCLAS_SE_CD", "");
			    dmOutcomeDetail.setValue("OCCP_ABILIT_STRNGT_MDSTRM_FAILR_CS_SCLAS_SE_CD", "");
			    dmOutcomeDetail.setValue("OCCP_ABILIT_STRNGT_MDSTRM_FAILR_CS_ETC_CN", "");
			}
